-- Mercaz: private backend schema. No browser access to orders, addresses or payment tokens.
BEGIN;
CREATE SCHEMA IF NOT EXISTS mercaz;
SET LOCAL search_path = mercaz, public;
  
CREATE TABLE IF NOT EXISTS users(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL DEFAULT '',supabase_id UUID UNIQUE REFERENCES auth.users(id) ON DELETE RESTRICT,address TEXT NOT NULL DEFAULT '{}',created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS stores(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER UNIQUE NOT NULL REFERENCES users(id),name TEXT NOT NULL,description TEXT NOT NULL,prep_days INTEGER NOT NULL DEFAULT 2,shipping INTEGER NOT NULL DEFAULT 1990,shipping_days INTEGER NOT NULL DEFAULT 5,paused INTEGER NOT NULL DEFAULT 0,days TEXT NOT NULL DEFAULT 'Segunda a sexta',document TEXT NOT NULL DEFAULT '',mp_token TEXT,mp_refresh TEXT,mp_expires BIGINT,created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,store_id INTEGER NOT NULL REFERENCES stores(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),stock INTEGER NOT NULL CHECK(stock>=0),images TEXT NOT NULL,variants TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'active',views INTEGER NOT NULL DEFAULT 0,created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),store_id INTEGER NOT NULL REFERENCES stores(id),status TEXT NOT NULL DEFAULT 'pending',subtotal INTEGER NOT NULL,shipping INTEGER NOT NULL,fee INTEGER NOT NULL,total INTEGER NOT NULL,address TEXT NOT NULL,prep_days INTEGER NOT NULL,shipping_days INTEGER NOT NULL,payment_id TEXT,payment_data TEXT NOT NULL DEFAULT '{}',tracking TEXT NOT NULL DEFAULT '',demo INTEGER NOT NULL,checkout_key TEXT NOT NULL,created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),product_id INTEGER NOT NULL REFERENCES products(id),title TEXT NOT NULL,image TEXT NOT NULL,variant TEXT NOT NULL,qty INTEGER NOT NULL,price INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),status TEXT NOT NULL,created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reviews(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),product_id INTEGER NOT NULL REFERENCES products(id),user_id INTEGER NOT NULL REFERENCES users(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),text TEXT NOT NULL,media TEXT NOT NULL DEFAULT '[]',context TEXT NOT NULL DEFAULT '',hidden INTEGER NOT NULL DEFAULT 0,created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(order_id,product_id));
CREATE TABLE IF NOT EXISTS reactions(review_id INTEGER NOT NULL REFERENCES reviews(id),user_id INTEGER NOT NULL REFERENCES users(id),PRIMARY KEY(review_id,user_id));
CREATE TABLE IF NOT EXISTS reports(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,review_id INTEGER NOT NULL REFERENCES reviews(id),user_id INTEGER NOT NULL REFERENCES users(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS questions(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id),user_id INTEGER NOT NULL REFERENCES users(id),question TEXT NOT NULL,answer TEXT NOT NULL DEFAULT '',created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tickets(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),user_id INTEGER NOT NULL REFERENCES users(id),type TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ticket_id INTEGER NOT NULL REFERENCES tickets(id),user_id INTEGER NOT NULL REFERENCES users(id),text TEXT NOT NULL,created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS favorites(user_id INTEGER NOT NULL REFERENCES users(id),kind TEXT NOT NULL,item_id INTEGER NOT NULL,PRIMARY KEY(user_id,kind,item_id));
CREATE TABLE IF NOT EXISTS notifications(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),text TEXT NOT NULL,href TEXT NOT NULL,seen INTEGER NOT NULL DEFAULT 0,created TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS uploads(path TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS oauth(state TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS payment_requests(order_id TEXT PRIMARY KEY REFERENCES orders(id),payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_products_store ON products(store_id);
CREATE INDEX IF NOT EXISTS idx_orders_user ON orders(user_id,created);
CREATE INDEX IF NOT EXISTS idx_orders_store ON orders(store_id,created);
CREATE INDEX IF NOT EXISTS idx_orders_payment ON orders(payment_id);
CREATE INDEX IF NOT EXISTS idx_reviews_product ON reviews(product_id);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id);

CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower ON users(lower(email));
CREATE UNIQUE INDEX IF NOT EXISTS orders_checkout_unique ON orders(user_id,checkout_key,store_id);
CREATE INDEX IF NOT EXISTS idx_items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS idx_events_order ON events(order_id,id);
CREATE INDEX IF NOT EXISTS idx_questions_product ON questions(product_id);
CREATE INDEX IF NOT EXISTS idx_tickets_user ON tickets(user_id);
CREATE INDEX IF NOT EXISTS idx_messages_ticket ON messages(ticket_id,id);
REVOKE ALL ON SCHEMA mercaz FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA mercaz FROM PUBLIC, anon, authenticated;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA mercaz FROM PUBLIC, anon, authenticated;
ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE stores ENABLE ROW LEVEL SECURITY;
ALTER TABLE products ENABLE ROW LEVEL SECURITY;
ALTER TABLE orders ENABLE ROW LEVEL SECURITY;
ALTER TABLE order_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE events ENABLE ROW LEVEL SECURITY;
ALTER TABLE reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE reactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE questions ENABLE ROW LEVEL SECURITY;
ALTER TABLE tickets ENABLE ROW LEVEL SECURITY;
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE favorites ENABLE ROW LEVEL SECURITY;
ALTER TABLE notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE uploads ENABLE ROW LEVEL SECURITY;
ALTER TABLE oauth ENABLE ROW LEVEL SECURITY;
ALTER TABLE payment_requests ENABLE ROW LEVEL SECURITY;
-- The BFF connects using the database credential, never an anon/service key in the browser.
-- No policies grant direct Data API access. Authorization stays in the existing Express API.
COMMIT;
